do $guard$ declare definition text; begin select pg_get_functiondef('public.admin_purge_test_data()'::regprocedure) into definition; if position('perform public.assert_is_admin();' in definition)=0 then execute regexp_replace(definition,'\mbegin\M',E'begin\n perform public.assert_is_admin();','i'); end if; end $guard$; revoke execute on function public.admin_purge_test_data() from public,anon;
